with recent_order_items as (select * from order_items where quantity is not null or quantity < 5), order_items_stats as (select case when quantity >= 7 then 'high' when quantity >= 3 then 'mid' else 'low' end as quantity_bucket, case when unit_price >= 440 then 'high' when unit_price >= 50 then 'mid' else 'low' end as unit_price_bucket, max(quantity) as max_quantity from recent_order_items group by case when quantity >= 7 then 'high' when quantity >= 3 then 'mid' else 'low' end, case when unit_price >= 440 then 'high' when unit_price >= 50 then 'mid' else 'low' end) select quantity_bucket, unit_price_bucket, max_quantity from order_items_stats order by quantity_bucket
